using System;using System.IO;using System.Text;using System.Diagnostics;using System.Linq;
internal static partial class NativeBackground {
 internal static string PaletteDiagnostic(){var s=new StringBuilder();s.AppendLine("Window="+Fingerprint());foreach(var p in Process.GetProcessesByName("Weixin")){using(p)try{if(p.MainWindowHandle==IntPtr.Zero)continue;long image=0;foreach(ProcessModule m in p.Modules)if(m.ModuleName.Equals("Weixin.dll",StringComparison.OrdinalIgnoreCase))image=m.BaseAddress.ToInt64();if(image==0)continue;var h=OpenProcess(0x410,false,p.Id);try{int mode=Read(h,image+AppearanceFlag+2,1)[0];s.AppendLine("Process="+p.Id+" mode="+mode+" mainRoot="+MainRootVisible(h,image));var t=Engine.ActiveTheme;for(int key=0;key<8;key++){int index=PaletteIndexes[key];s.AppendLine(Palette.Keys[key]+" expected="+(t==null?"no saved theme":t.Colors[key*2+Math.Min(mode,1)])+" dual="+BitConverter.ToString(Read(h,image+PaletteDual+index*8,8))+" active="+BitConverter.ToString(Read(h,image+PaletteColors+index*24,16)));}}finally{CloseHandle(h);}}catch(Exception e){s.AppendLine("Read error="+e.Message);}}return s.ToString();}
}
internal static class RenderDiagnostic {
 internal static string Run(){var s=new StringBuilder();s.AppendLine("WeixinThemeStudio render diagnostics 6.6.1");s.AppendLine("No chat content, screenshots, account databases or wallpaper included.");s.AppendLine("UTC="+DateTime.UtcNow.ToString("o"));s.AppendLine("OS="+Environment.OSVersion+" x64="+Environment.Is64BitOperatingSystem);try{s.AppendLine("Install="+Engine.Target);s.AppendLine("Installed length="+new FileInfo(Engine.Target).Length);}catch(Exception e){s.AppendLine(e.Message);}try{s.AppendLine(NativeBackground.PaletteDiagnostic());}catch(Exception e){s.AppendLine("Palette error="+e.Message);}foreach(string key in new[]{"background-service.txt","background-worker.txt","auto-background.log","appearance-observed.txt","whole-background-plan.txt"}){s.AppendLine("--- "+key);try{string value=File.ReadAllText(Path.Combine(Engine.Store,key));s.AppendLine(value.Substring(0,Math.Min(value.Length,12000)));}catch{s.AppendLine("not present");}}s.AppendLine("Whole="+NativeBackground.WholeEnabled);string output=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"渲染诊断.txt");File.WriteAllText(output,s.ToString(),Encoding.UTF8);return output;}
}
